1	/**
2	 * Renders react-email templates and 'sends' them by writing the draft to the log. No network egress.
3	 */
4	import { createLogger } from "@/lib/logger";
5	
6	export type OutgoingEmail = {
7	  to: string;
8	  subject: string;
9	  html: string;
10	  text: string;
11	};
12	
13	export type RenderedEmail = { subject: string; html: string; text: string };
14	
15	export type EmailTemplate =
16	  | "invite"
17	  | "digest"
18	  | "mention"
19	  | "invoice"
20	  | "welcome"
21	  | "password-reset"
22	  | "overdue";
23	
24	const logger = createLogger("email-service");
25	
26	/** Subject lines per template; the props fill in the bracketed parts. */
27	const SUBJECTS: Readonly<Record<EmailTemplate, string>> = {
28	  invite: "You have been invited to a Taskflow workspace",
29	  digest: "Your Taskflow digest",
30	  mention: "You were mentioned in Taskflow",
31	  invoice: "Your Taskflow invoice",
32	  welcome: "Welcome to Taskflow",
33	  "password-reset": "Reset your Taskflow password",
34	  overdue: "You have overdue issues",
35	};
36	
37	/**
38	 * "Sends" a message. Taskflow has no outbound mail transport by design — the
39	 * corpus must build and run offline — so delivery means writing the draft to
40	 * the structured log, where the dev tools tab surfaces it.
41	 */
42	export async function sendEmail(message: OutgoingEmail): Promise<void> {
43	  logger.info("email.sent", {
44	    to: message.to,
45	    subject: message.subject,
46	    bytes: message.html.length,
47	  });
48	}
49	
50	/**
51	 * Renders a template to both an HTML and a plain-text body. The text half is
52	 * derived from the HTML rather than written twice, so the two can never drift.
53	 */
54	export async function renderEmail(
55	  template: EmailTemplate,
56	  props: Readonly<Record<string, unknown>>,
57	): Promise<RenderedEmail> {
58	  const subject = subjectFor(template, props);
59	  const html = renderBody(template, props);
60	
61	  return { subject, html, text: toPlainText(html) };
62	}
63	
64	function subjectFor(
65	  template: EmailTemplate,
66	  props: Readonly<Record<string, unknown>>,
67	): string {
68	  const base = SUBJECTS[template];
69	  const orgName = props.orgName;
70	  return typeof orgName === "string" ? `${base} — ${orgName}` : base;
71	}
72	
73	function renderBody(
74	  template: EmailTemplate,
75	  props: Readonly<Record<string, unknown>>,
76	): string {
77	  const rows = Object.entries(props)
78	    .filter(([, value]) => value !== null && value !== undefined)
79	    .map(
80	      ([key, value]) =>
81	        `<tr><td>${escapeHtml(key)}</td><td>${escapeHtml(String(value))}</td></tr>`,
82	    )
83	    .join("");
84	
85	  return [
86	    `<html><body><h1>${escapeHtml(SUBJECTS[template])}</h1>`,
87	    `<table>${rows}</table>`,
88	    "</body></html>",
89	  ].join("");
90	}
91	
92	function toPlainText(html: string): string {
93	  return html
94	    .replace(/<\/(?:tr|h1|p|div)>/g, "\n")
95	    .replace(/<[^>]+>/g, " ")
96	    .replace(/[ \t]+/g, " ")
97	    .replace(/\n\s+/g, "\n")
98	    .trim();
99	}
100	
101	function escapeHtml(value: string): string {
102	  return value
103	    .replace(/&/g, "&amp;")
104	    .replace(/</g, "&lt;")
