1	/**
2	 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
3	 *
4	 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
5	 */
6	import { isEnabled } from "@/lib/feature-flags";
7	import { createLogger } from "@/lib/logger";
8	import * as notificationRepo from "@/server/repositories/notification-repository";
9	import * as orgRepo from "@/server/repositories/organization-repository";
10	import * as usageRepo from "@/server/repositories/usage-repository";
11	import * as userRepo from "@/server/repositories/user-repository";
12	import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
13	import { sendEmail } from "@/server/services/email-service";
14	import { buildFlagContext } from "@/server/services/feature-flag-service";
15	import { toIsoTimestamp } from "@/types/common";
16	import { runJob } from "./types";
17	import type { JobResult } from "@/server/jobs/types";
18	import type { Organization } from "@/types/organization";
19	
20	const ORG_BATCH = 50;
21	const MS_PER_DAY = 24 * 60 * 60 * 1000;
22	
23	const logger = createLogger("digest-email-job");
24	
25	/**
26	 * One pass per scheduler tick. Each org is only processed during the UTC hour
27	 * it configured, so a tick that runs every few minutes still sends exactly one
28	 * digest per day per recipient.
29	 */
30	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
31	  return runJob("digest-email", async (result) => {
32	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
33	
34	    for (const orgId of orgIds) {
35	      const org = await orgRepo.findOrgById(orgId);
36	      if (!org || !shouldRunForOrg(org, now)) continue;
37	
38	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
39	
40	      const windowEnd = toIsoTimestamp(now);
41	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
42	
43	      for (const recipientId of await listDigestRecipients(orgId)) {
44	        try {
45	          const bundle = await buildDigest(
46	            orgId,
47	            recipientId,
48	            windowStart,
49	            windowEnd,
50	          );
51	          if (!bundle) continue;
52	
53	          const recipient = await userRepo.findUserById(recipientId);
54	          if (!recipient) continue;
55	
56	          const rendered = await renderDigest(bundle, recipient);
57	          await sendEmail({ to: recipient.email, ...rendered });
58	
59	          // Once digested, these notifications are no longer "unread" — this
60	          // is what keeps a later run inside the same window from sending
61	          // the same digest twice.
62	          for (const entry of bundle.entries) {
63	            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
64	          }
65	
66	          result.processed += 1;
67	        } catch (error) {
68	          result.failed += 1;
69	          logger.error("digest failed", {
70	            orgId,
71	            recipientId,
72	            reason: error instanceof Error ? error.message : String(error),
73	          });
74	        }
75	      }
76	    }
77	  });
78	}
79	
80	/**
81	 * True during the org's configured digest hour. Exported because the schedule
